import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    record ProblemDetail(String type, String title, int status, String detail) {}
    record ItemRequest(String sku, int quantidade) {}
    record ItemPedido(String sku, int quantidade) {}
    record PedidoRequest(String clienteId, List<ItemRequest> itens) {}
    record Pedido(long id, String clienteId, List<ItemPedido> itens, String status) {}

    static class RecursoNaoEncontradoException extends RuntimeException {
        RecursoNaoEncontradoException(String message) { super(message); }
    }
    static class ValidacaoException extends RuntimeException {
        ValidacaoException(String message) { super(message); }
    }
    static class ConflitoException extends RuntimeException {
        ConflitoException(String message) { super(message); }
    }

    static class PedidoService {
        private final Map<Long, Pedido> pedidos = new HashMap<>();
        private long proximoId = 1;

        Pedido criar(PedidoRequest request) {
            if (request == null || request.clienteId() == null || request.clienteId().isBlank()) {
                throw new ValidacaoException("clienteId obrigatorio");
            }
            if (request.itens() == null || request.itens().isEmpty()) {
                throw new ValidacaoException("pedido precisa de ao menos um item");
            }
            var itens = new ArrayList<ItemPedido>();
            for (var item : request.itens()) {
                if (item == null) throw new ValidacaoException("item nulo");
                if (item.sku() == null || item.sku().isBlank()) {
                    throw new ValidacaoException("sku obrigatorio");
                }
                if (item.quantidade() <= 0) {
                    throw new ValidacaoException("quantidade deve ser positiva");
                }
                itens.add(new ItemPedido(item.sku(), item.quantidade()));
            }
            long id = proximoId++;
            var pedido = new Pedido(id, request.clienteId(), List.copyOf(itens), "CRIADO");
            pedidos.put(id, pedido);
            return pedido;
        }

        Pedido buscar(long id) {
            var pedido = pedidos.get(id);
            if (pedido == null) throw new RecursoNaoEncontradoException("pedido " + id + " nao encontrado");
            return pedido;
        }

        void cancelar(long id) {
            var pedido = buscar(id);
            if (!"CRIADO".equals(pedido.status())) {
                throw new ConflitoException("pedido " + id + " nao pode ser cancelado no status " + pedido.status());
            }
            pedidos.put(id, new Pedido(pedido.id(), pedido.clienteId(), pedido.itens(), "CANCELADO"));
        }

        int total() { return pedidos.size(); }
    }

    static class ProblemDetailMapper {
        ProblemDetail mapear(RuntimeException erro) {
            if (erro == null) throw new IllegalArgumentException("erro obrigatorio");
            String detail = erro.getMessage() == null ? "" : erro.getMessage();
            if (erro instanceof RecursoNaoEncontradoException) {
                return new ProblemDetail("about:blank", "Recurso não encontrado", 404,
                    detail.isEmpty() ? "Recurso não encontrado" : detail);
            }
            if (erro instanceof ValidacaoException) {
                return new ProblemDetail("about:blank", "Requisição inválida", 400,
                    detail.isEmpty() ? "Requisição inválida" : detail);
            }
            if (erro instanceof ConflitoException) {
                return new ProblemDetail("about:blank", "Conflito de estado", 409,
                    detail.isEmpty() ? "Conflito de estado" : detail);
            }
            return new ProblemDetail("about:blank", "Erro interno", 500,
                detail.isEmpty() ? "Erro interno" : detail);
        }
    }
}

