import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.ArrayList;
import java.util.List;

class SolutionTest {
    private Solution.PedidoRequest request(String cliente, String sku, int qtd) {
        return new Solution.PedidoRequest(cliente, List.of(new Solution.ItemRequest(sku, qtd)));
    }

    @Test void criaEBusca() {
        var service = new Solution.PedidoService();
        var pedido = service.criar(request("c1", "SKU-1", 2));
        assertEquals(1, pedido.id());
        assertEquals("CRIADO", pedido.status());
        assertEquals(pedido, service.buscar(1));
        assertEquals(1, service.total());
    }

    @Test void validacoesDeCriacao() {
        var service = new Solution.PedidoService();
        assertThrows(Solution.ValidacaoException.class,
            () -> service.criar(new Solution.PedidoRequest("", List.of(new Solution.ItemRequest("S", 1)))));
        assertThrows(Solution.ValidacaoException.class,
            () -> service.criar(new Solution.PedidoRequest("c1", List.of())));
        assertThrows(Solution.ValidacaoException.class,
            () -> service.criar(request("c1", " ", 1)));
        assertThrows(Solution.ValidacaoException.class,
            () -> service.criar(request("c1", "S", 0)));
    }

    @Test void naoEncontrado() {
        var service = new Solution.PedidoService();
        assertThrows(Solution.RecursoNaoEncontradoException.class, () -> service.buscar(99));
        assertThrows(Solution.RecursoNaoEncontradoException.class, () -> service.cancelar(99));
    }

    @Test void cancelamentoUnico() {
        var service = new Solution.PedidoService();
        service.criar(request("c1", "S", 1));
        service.cancelar(1);
        assertEquals("CANCELADO", service.buscar(1).status());
        assertThrows(Solution.ConflitoException.class, () -> service.cancelar(1));
    }

    @Test void requestNaoCompartilhaLista() {
        var itens = new ArrayList<Solution.ItemRequest>();
        itens.add(new Solution.ItemRequest("S", 1));
        var req = new Solution.PedidoRequest("c1", itens);
        var service = new Solution.PedidoService();
        var pedido = service.criar(req);
        itens.clear();
        assertEquals(1, pedido.itens().size());
    }

    @Test void mapperTraduzCadaExcecao() {
        var mapper = new Solution.ProblemDetailMapper();

        var naoEncontrado = mapper.mapear(new Solution.RecursoNaoEncontradoException("sumiu"));
        assertEquals(404, naoEncontrado.status());
        assertEquals("about:blank", naoEncontrado.type());
        assertEquals("sumiu", naoEncontrado.detail());

        var invalido = mapper.mapear(new Solution.ValidacaoException("campo x"));
        assertEquals(400, invalido.status());
        assertEquals("Requisição inválida", invalido.title());

        var conflito = mapper.mapear(new Solution.ConflitoException("estado"));
        assertEquals(409, conflito.status());

        var interno = mapper.mapear(new RuntimeException("boom"));
        assertEquals(500, interno.status());
        assertEquals("Erro interno", interno.title());
    }

    @Test void mapperSemMensagemUsaTitulo() {
        var mapper = new Solution.ProblemDetailMapper();
        var detalhe = mapper.mapear(new Solution.ValidacaoException(null));
        assertEquals("Requisição inválida", detalhe.detail());
    }
}
